178	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
179	
180	const hasHighEnchantmentForClaim = (item: Item): boolean =>
181	  enchantmentOf(item) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD;
182	
183	const reimbursementRate = (item: Item): number =>
184	  hasHighEnchantmentForClaim(item) ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
185	
186	const damagePayout = (damage: Damage, item: Item): number =>
187	  Math.max(0, damage.amount * reimbursementRate(item) - DEDUCTIBLE);
188	
189	const requireItemByType = (policy: Policy, itemType: string): Item => {
190	  const item = policy.items.find((candidate) => candidate.type === itemType);
191	  if (item === undefined) throw new Error(`Claim references item not in policy: ${itemType}`);
192	  return item;
193	};
194	
195	const payoutForDamage = (damage: Damage, policy: Policy): number =>
196	  damagePayout(damage, requireItemByType(policy, damage.itemType));
197	
198	const calculatePayout = (damages: Damage[], policy: Policy): number => {
199	  const rawPayout = sumBy(damages, (damage) => payoutForDamage(damage, policy));
200	  return roundDownInMHPCOsFavor(Math.min(rawPayout, policy.remainingCap));
201	};
202	
203	const assertNonNegativeDamage = (damage: Damage): void => {
204	  if (damage.amount < 0) throw new Error(`Negative damage amount: ${damage.amount}`);
205	};
206	
207	const assertDamageCountsWithinPolicy = (damages: Damage[], policy: Policy): void => {
208	  const insuredCounts = countItemsByType(policy.items);
209	  const damageCounts = countByKey(damages, (damage) => damage.itemType);
210	  for (const [type, count] of damageCounts) {
211	    if (count > (insuredCounts.get(type) ?? 0)) {
212	      throw new Error(`More damages of type ${type} than items insured`);
213	    }
214	  }
215	};
216	
217	const processClaim = (step: ClaimStep, policies: Policy[]): ClaimResult => {
218	  const { damages } = step.incident;
219	  const policy = policies[step.policy];
220	  damages.forEach(assertNonNegativeDamage);
221	  assertDamageCountsWithinPolicy(damages, policy);
222	  const payout = calculatePayout(damages, policy);
223	  policy.remainingCap -= payout;
224	  return { payout, remainingCap: policy.remainingCap };
225	};
226	
227	const assertKnownItemType = (item: Item): void => {
228	  if (!(item.type in CATALOG)) throw new Error(`Unknown item type: ${item.type}`);
229	};
230	
231	const processQuote = (
232	  step: QuoteStep,
233	  customer: Customer,
234	  policies: Policy[],
235	): QuoteResult => {
236	  step.items.forEach(assertKnownItemType);
237	  const context: QuoteContext = { customer, isFollowUp: policies.length > 0 };
238	  policies.push(createPolicy(step));
239	  return { premium: quotePremium(step, context) };
240	};
241	
242	const processStep = (
243	  step: Step,
244	  customer: Customer,
245	  policies: Policy[],
246	): StepResult =>
247	  step.op === "quote"
248	    ? processQuote(step, customer, policies)
249	    : processClaim(step, policies);
250	
251	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
252	  const policies: Policy[] = [];
253	  const results = steps.map((step) => processStep(step, customer, policies));
254	  return { results };
255	};
